"""Tests for roman.py."""

import pytest
from roman import to_roman, from_roman


class TestToRoman:
    """Tests for to_roman()."""

    def test_one(self):
        assert to_roman(1) == "I"

    def test_two(self):
        assert to_roman(2) == "II"

    def test_three(self):
        assert to_roman(3) == "III"

    def test_four(self):
        assert to_roman(4) == "IV"

    def test_five(self):
        assert to_roman(5) == "V"

    def test_nine(self):
        assert to_roman(9) == "IX"

    def test_ten(self):
        assert to_roman(10) == "X"

    def test_forty(self):
        assert to_roman(40) == "XL"

    def test_fifty(self):
        assert to_roman(50) == "L"

    def test_ninety(self):
        assert to_roman(90) == "XC"

    def test_hundred(self):
        assert to_roman(100) == "C"

    def test_four_hundred(self):
        assert to_roman(400) == "CD"

    def test_five_hundred(self):
        assert to_roman(500) == "D"

    def test_nine_hundred(self):
        assert to_roman(900) == "CM"

    def test_thousand(self):
        assert to_roman(1000) == "M"

    def test_two_thousand(self):
        assert to_roman(2000) == "MM"

    def test_three_thousand_nine_hundred_ninety_nine(self):
        assert to_roman(3999) == "MMMCMXCIX"

    # Boundary: minimum
    def test_minimum_range(self):
        assert to_roman(1) == "I"

    # Boundary: maximum
    def test_maximum_range(self):
        assert to_roman(3999) == "MMMCMXCIX"

    # Out of range
    def test_zero_raises(self):
        with pytest.raises(ValueError):
            to_roman(0)

    def test_negative_raises(self):
        with pytest.raises(ValueError):
            to_roman(-1)

    def test_above_max_raises(self):
        with pytest.raises(ValueError):
            to_roman(4000)

    # Non-integer types
    def test_float_raises(self):
        with pytest.raises(ValueError):
            to_roman(1.0)

    def test_string_raises(self):
        with pytest.raises(ValueError):
            to_roman("1")

    def test_bool_raises(self):
        with pytest.raises(ValueError):
            to_roman(True)

    def test_none_raises(self):
        with pytest.raises(ValueError):
            to_roman(None)

    # Representative values across the range
    def test_representative_values(self):
        assert to_roman(7) == "VII"
        assert to_roman(12) == "XII"
        assert to_roman(21) == "XXI"
        assert to_roman(99) == "XCIX"
        assert to_roman(199) == "CXCIX"
        assert to_roman(499) == "CDXCIX"
        assert to_roman(999) == "CMXCIX"
        assert to_roman(1999) == "MCMXCIX"
        assert to_roman(2024) == "MMXXIV"
        assert to_roman(3000) == "MMM"
        assert to_roman(3998) == "MMMCMXCVIII"


class TestFromRoman:
    """Tests for from_roman()."""

    def test_i(self):
        assert from_roman("I") == 1

    def test_ii(self):
        assert from_roman("II") == 2

    def test_iii(self):
        assert from_roman("III") == 3

    def test_iv(self):
        assert from_roman("IV") == 4

    def test_v(self):
        assert from_roman("V") == 5

    def test_ix(self):
        assert from_roman("IX") == 9

    def test_x(self):
        assert from_roman("X") == 10

    def test_xl(self):
        assert from_roman("XL") == 40

    def test_l(self):
        assert from_roman("L") == 50

    def test_xc(self):
        assert from_roman("XC") == 90

    def test_c(self):
        assert from_roman("C") == 100

    def test_cd(self):
        assert from_roman("CD") == 400

    def test_d(self):
        assert from_roman("D") == 500

    def test_cm(self):
        assert from_roman("CM") == 900

    def test_m(self):
        assert from_roman("M") == 1000

    def test_mmm_cm_xc_ix(self):
        assert from_roman("MMMCMXCIX") == 3999

    # Round-trip: every value in range
    @pytest.mark.parametrize("n", list(range(1, 4000)))
    def test_roundtrip_all(self, n):
        assert from_roman(to_roman(n)) == n

    # Invalid forms
    def test_empty_string_raises(self):
        with pytest.raises(ValueError):
            from_roman("")

    def test_repeated_iiii_raises(self):
        with pytest.raises(ValueError):
            from_roman("IIII")

    def test_double_v_raises(self):
        with pytest.raises(ValueError):
            from_roman("VV")

    def test_ic_raises(self):
        with pytest.raises(ValueError):
            from_roman("IC")

    def test_xm_raises(self):
        with pytest.raises(ValueError):
            from_roman("XM")

    def test_mmmm_raises(self):
        with pytest.raises(ValueError):
            from_roman("MMMM")

    def test_banana_raises(self):
        with pytest.raises(ValueError):
            from_roman("banana")

    # Non-string types
    def test_int_raises(self):
        with pytest.raises(ValueError):
            from_roman(1)

    def test_float_raises(self):
        with pytest.raises(ValueError):
            from_roman(3.14)

    def test_bool_raises(self):
        with pytest.raises(ValueError):
            from_roman(True)

    def test_none_raises(self):
        with pytest.raises(ValueError):
            from_roman(None)

    # Lowercase not valid
    def test_lowercase_raises(self):
        with pytest.raises(ValueError):
            from_roman("iv")

    # Other invalid subtractive combinations
    def test_iq_raises(self):
        with pytest.raises(ValueError):
            from_roman("IQ")

    def test_xv_raises(self):
        with pytest.raises(ValueError):
            from_roman("XV")

    def test_il_raises(self):
        with pytest.raises(ValueError):
            from_roman("IL")

    def test_ic_raises_strict(self):
        with pytest.raises(ValueError):
            from_roman("IC")

    def test_im_raises(self):
        with pytest.raises(ValueError):
            from_roman("IM")

    def test_lc_raises(self):
        with pytest.raises(ValueError):
            from_roman("LC")

    def test_ld_raises(self):
        with pytest.raises(ValueError):
            from_roman("LD")

    def test_lm_raises(self):
        with pytest.raises(ValueError):
            from_roman("LM")

    def test_dm_raises(self):
        with pytest.raises(ValueError):
            from_roman("DM")

    def test_dn_raises(self):
        with pytest.raises(ValueError):
            from_roman("DN")

    def test_dc_raises(self):
        with pytest.raises(ValueError):
            from_roman("DC")
